query ($boardId: [ID!]) {
  # The account's users. A people CELL carries monday's person id and the
  # activity log carries only a user id — neither is a name, and this is the one
  # thing that turns either into one. Without it a people column can only be
  # matched by display name, and every log row reads "מערכת".
  #
  # The limit is not decoration. Asked bare, `users` answers with monday's
  # default page of 200 and says nothing about the rest — on this account that
  # is 200 of 318, and the 118 it leaves out are ordinary named people with
  # ordinary company addresses. They came back from an import as "could not be
  # matched", which reads like they are not in the system rather than like the
  # export never asked about them.
  users(limit: 1000) {
    id
    name
    email
  }

  boards(ids: $boardId) {
    id
    name
    # How many items the board holds, against the 500 that fit in one page. It
    # is what turns "did everything come?" into arithmetic instead of a feeling:
    # 687 against 500 says a second request is needed before the first response
    # is even read, and it is the number the pages are counted back against.
    #
    # It is read by the importer now, which it was not: the field came across in
    # the file and nothing compared it to anything. A merged file of 2,000 items
    # out of a 2,069-item board imported as a board of 2,000, and the gap was
    # found by counting one group in monday a day later. The report states both
    # numbers — see items_expected / items_missing in import_monday.parse.
    items_count

    groups { id title color }
    # The board's own column definitions. Two things live ONLY here — the copy of
    # a column that rides inside every item carries its title and type and
    # nothing else — and `settings_str` is the JSON holding both.
    #
    # A formula, as the expression itself:
    #   {"formula": "{numeric_mkl3sp} + 5"}   (references are column IDs)
    # and a status column's vocabulary, as the words beside their colours:
    #   {"labels": {"0": "בעבודה", "1": "הושלם"},
    #    "labels_colors": {"0": {"color": "#fdab3d"}, "1": {"color": "#00c875"}}}
    # Without this line every status arrives in a colour of this app's choosing,
    # cycled by position — so "הושלם" comes across red as often as green, and
    # the board can no longer be read at a glance the way it could in monday.
    # It is the deprecated spelling of the typed `settings` object, and it is
    # asked for deliberately: it exists in every API version this export runs
    # against, while `settings` does not. The importer reads either shape.
    columns { id title type settings_str }
    items_page(limit: 500) {
      cursor
      items {
        id
        name
        group { id title color }
        column_values {
          id
          type
          column { title }
          text
          value
          ... on FileValue { files { ... on FileAssetValue { asset_id } } }
          # Three types do not answer in `text` at all, and asking only for it
          # is what made them arrive empty on every single item:
          #   board_relation — "the text and value fields always return null"
          #   mirror         — the mirrored content lives in display_value
          #   formula        — "the computed result is returned in display_value;
          #                     the text and value fields are not populated"
          ... on BoardRelationValue { display_value linked_item_ids linked_items { id name } }
          ... on MirrorValue { display_value }
          # ⚠ monday allows at most FIVE formula columns per request (and 10,000
          # formula values a minute). A board with more than five gets an error or
          # empty strings back: export it twice, each run naming a different set
          # of column `ids`, or drop this line and accept that the formulas —
          # which are computed, never stored — do not come across.
          ... on FormulaValue { display_value }
        }
        assets { id name public_url }
        subitems {
          id
          name
          column_values {
            id type column { title } text value
            ... on FileValue { files { ... on FileAssetValue { asset_id } } }
            ... on BoardRelationValue { display_value linked_item_ids linked_items { id name } }
            ... on MirrorValue { display_value }
            ... on FormulaValue { display_value }
          }
          # A file cell names its asset, and the asset — its real name and the link
          # that can actually be fetched — is carried by the ROW the cell sits on.
          # Asked for on the items and not on their sub-items, every file attached to
          # a sub-item arrived as a bare name with nothing behind it.
          assets { id name public_url }
          updates {
            id body text_body created_at
            creator { name email }
            replies { id body text_body created_at creator { name email } assets { id name public_url } }
            assets { id name public_url }
          }
        }
        updates {
          id body text_body created_at
          creator { name email }
          replies { id body text_body created_at creator { name email } assets { id name public_url } }
          assets { id name public_url }
        }
      }
    }
  }
}

query ($boardId: [ID!], $page: Int!) {
  # limit: see the first query — bare, this answers with 200 of 318
  users(limit: 1000) {
    id
    name
    email
  }

  boards(ids: $boardId) {
    id
    activity_logs(limit: 10000, page: $page) {
      id
      event
      data
      user_id
      created_at
    }
  }
}

query ($cursor: String!) {
